import pandas as pd
df = pd.read_csv("nlo_pool.csv")
from pymatgen.core import Composition
import numpy as np
from pymatgen.core.periodic_table import Element

def get_mean_Z(formula):
    try:
        comp = Composition(formula)
        Z_vals = []
        for el, amt in comp.get_el_amt_dict().items():
            Z_vals.extend([Element(el).Z]*int(amt))
        return np.mean(Z_vals)
    except:
        return 0

df['mean_Z'] = df['formula'].apply(get_mean_Z)
print(df.nlargest(15, 'mean_Z')[['candidate_id', 'formula', 'mean_Z']].to_string())

import pandas as pd
from pymatgen.core import Structure
import numpy as np
from pymatgen.core.periodic_table import Element
from sklearn.metrics.pairwise import cosine_similarity, euclidean_distances

df_train = pd.read_csv("nlo_dn_train.csv")
df_pool = pd.read_csv("nlo_pool.csv")

def get_comp_vector(formula):
    try:
        comp = Structure.from_str(formula, fmt="poscar").composition if '1.0' in formula else pd.core.composition.Composition(formula)
        return {el.symbol: amt for el, amt in comp.get_el_amt_dict().items()}
    except:
        return {}

def get_comp_frac_vector(poscar_str):
    try:
        comp = Structure.from_str(poscar_str, fmt="poscar").composition
        return comp.fractional_composition.as_dict()
    except:
        return {}

train_comps = [get_comp_frac_vector(p) for p in df_train['poscar']]
pool_comps = [get_comp_frac_vector(p) for p in df_pool['poscar']]

all_elements = set()
for c in train_comps + pool_comps:
    all_elements.update(c.keys())
all_elements = sorted(list(all_elements))

X_train_comp = np.zeros((len(train_comps), len(all_elements)))
for i, c in enumerate(train_comps):
    for j, el in enumerate(all_elements):
        X_train_comp[i, j] = c.get(el, 0)

X_pool_comp = np.zeros((len(pool_comps), len(all_elements)))
for i, c in enumerate(pool_comps):
    for j, el in enumerate(all_elements):
        X_pool_comp[i, j] = c.get(el, 0)

sims = cosine_similarity(X_pool_comp, X_train_comp)

print("Top 10 most similar pool candidates to high-dn train candidates:")
for p_idx in range(len(pool_comps)):
    max_sim_idx = np.argmax(sims[p_idx])
    max_sim = sims[p_idx][max_sim_idx]
    if max_sim > 0.8:
        t_dn = df_train.iloc[max_sim_idx]['dn']
        if t_dn > 0.3:
            print(f"{df_pool.iloc[p_idx]['candidate_id']} ({df_pool.iloc[p_idx]['formula']}) is {max_sim:.2f} similar to {df_train.iloc[max_sim_idx]['formula']} (dn={t_dn:.3f})")

